local SublimationApparatusMaker = {}
local PRODUCTS = {
    simple_glass_sublimation = { name = "Preprosta steklena sublimatorna naprava", glassCost = 3, clayCost = 1, time = 5, cost = 100, science = 22, happiness = 1, description = "Preprosta steklena sublimatorna naprava za sublimacijo." },
    brass_framed_sublimation = { name = "Medeninasto okvirjena sublimatorna naprava", glassCost = 3, brassCost = 2, clayCost = 1, time = 8, cost = 280, science = 38, happiness = 2, prestige = 2, description = "Medeninasto okvirjena sublimatorna naprava za trgovce." },
    silver_jointed_sublimation = { name = "Srebrnospojna sublimatorna naprava", glassCost = 4, silverCost = 1, brassCost = 2, clayCost = 1, time = 12, cost = 680, science = 52, happiness = 2, prestige = 6, description = "Srebrnospojna sublimatorna naprava za plemiče." },
    gold_trimmed_sublimation = { name = "Zlatookrasna sublimatorna naprava", glassCost = 4, goldCost = 1, silverCost = 1, brassCost = 2, clayCost = 1, time = 16, cost = 1600, science = 68, happiness = 3, prestige = 14, description = "Zlatookrasna sublimatorna naprava za visoke plemiče." },
    jewel_valve_sublimation = { name = "Draguljnoventilna sublimatorna naprava", glassCost = 5, goldCost = 1, silverCost = 1, brassCost = 2, clayCost = 1, jewelCost = 1, time = 20, cost = 3500, science = 82, happiness = 5, prestige = 27, description = "Sublimatorna naprava z draguljnim ventilom za visoko plemstvo." },
    royal_grand_sublimation = { name = "Kraljevski veliki sublimatorna naprava", glassCost = 7, goldCost = 2, silverCost = 2, brassCost = 2, clayCost = 1, jewelCost = 2, pearlCost = 2, time = 27, cost = 7500, science = 95, happiness = 12, prestige = 58, description = "Velika kraljevska sublimatorna naprava z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    sublimation_workshop = { name = "Sublimatorna delavnica", cost = { gold = 290, wood = 120, stone = 150, glass = 8, clay = 6 }, upkeep = 7, qualityBonus = 5 },
    alchemy_loft = { name = "Alkemična podstrešje", cost = { gold = 1050, wood = 280, stone = 280, silver = 6, brass = 6 }, upkeep = 24, qualityBonus = 18 },
    master_sublimation_atelier = { name = "Mojstrski sublimatorski atelje", cost = { gold = 2750, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 64, qualityBonus = 30 },
    royal_alchemy_palace = { name = "Kraljevska alkemična palača", cost = { gold = 11800, wood = 580, stone = 780, gold = 78, jewel = 18 }, upkeep = 235, qualityBonus = 55, prestigeBonus = 50 },
}
SublimationApparatusMaker.glassStock = 18; SublimationApparatusMaker.clayStock = 10; SublimationApparatusMaker.brassStock = 12; SublimationApparatusMaker.silverStock = 6; SublimationApparatusMaker.goldStock = 6; SublimationApparatusMaker.jewelStock = 4; SublimationApparatusMaker.pearlStock = 4
SublimationApparatusMaker.productStock = {}; SublimationApparatusMaker.buildings = {}; SublimationApparatusMaker.maker = nil; SublimationApparatusMaker.activeMaking = {}; SublimationApparatusMaker.totalProducts = 0; SublimationApparatusMaker.dayTimer = 0
function SublimationApparatusMaker.init() SublimationApparatusMaker.glassStock=18; SublimationApparatusMaker.clayStock=10; SublimationApparatusMaker.brassStock=12; SublimationApparatusMaker.silverStock=6; SublimationApparatusMaker.goldStock=6; SublimationApparatusMaker.jewelStock=4; SublimationApparatusMaker.pearlStock=4; SublimationApparatusMaker.productStock={}; SublimationApparatusMaker.buildings={}; SublimationApparatusMaker.maker=nil; SublimationApparatusMaker.activeMaking={}; SublimationApparatusMaker.totalProducts=0; SublimationApparatusMaker.dayTimer=0; print("[SublimationApparatusMaker] Royal Sublimation Apparatus Maker System initialized (6 products, 4 buildings)") end
function SublimationApparatusMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SublimationApparatusMaker.maker={name=n or ("Sublimator "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sublimator najet: %s (spretnost: %d)",SublimationApparatusMaker.maker.name,s),"success") end; return true end
function SublimationApparatusMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SublimationApparatusMaker.build(id) local ok,e=SublimationApparatusMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SublimationApparatusMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SublimationApparatusMaker.getQualityBonus() local b=0; for _,bd in ipairs(SublimationApparatusMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SublimationApparatusMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and SublimationApparatusMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.clayCost and SublimationApparatusMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.brassCost and SublimationApparatusMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.silverCost and SublimationApparatusMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SublimationApparatusMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SublimationApparatusMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SublimationApparatusMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SublimationApparatusMaker.buildings==0 then return false,"Potrebna sublimatorna delavnica" end; if not SublimationApparatusMaker.maker then return false,"Potreben sublimator" end; return true end
function SublimationApparatusMaker.make(pt,qty) qty=qty or 1; local ok,e=SublimationApparatusMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then SublimationApparatusMaker.glassStock=SublimationApparatusMaker.glassStock-d.glassCost*qty end; if d.clayCost then SublimationApparatusMaker.clayStock=SublimationApparatusMaker.clayStock-d.clayCost*qty end; if d.brassCost then SublimationApparatusMaker.brassStock=SublimationApparatusMaker.brassStock-d.brassCost*qty end; if d.silverCost then SublimationApparatusMaker.silverStock=SublimationApparatusMaker.silverStock-d.silverCost*qty end; if d.goldCost then SublimationApparatusMaker.goldStock=SublimationApparatusMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SublimationApparatusMaker.jewelStock=SublimationApparatusMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then SublimationApparatusMaker.pearlStock=SublimationApparatusMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if SublimationApparatusMaker.maker then t=math.max(1,t-math.floor(SublimationApparatusMaker.maker.skill/13)) end; table.insert(SublimationApparatusMaker.activeMaking,{id="sublimationapp_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,science=d.science or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SublimationApparatusMaker.completeMaking(m) local q=1.0+(SublimationApparatusMaker.getQualityBonus()/100); if SublimationApparatusMaker.maker then q=q+(SublimationApparatusMaker.maker.skill/140) end; q=math.min(2.5,q); SublimationApparatusMaker.productStock[m.productType]=(SublimationApparatusMaker.productStock[m.productType] or 0)+m.quantity; SublimationApparatusMaker.totalProducts=SublimationApparatusMaker.totalProducts+m.quantity; if m.science>0 and _G.state then _G.state.science=(_G.state.science or 0)+m.science end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SublimationApparatusMaker.maker then SublimationApparatusMaker.maker.itemsMade=SublimationApparatusMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SublimationApparatusMaker.maker.skill=math.min(100,SublimationApparatusMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sublimatorna naprava izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sublimationapp.completed",{productName=m.productName,science=m.science,prestige=m.prestige,happiness=m.happiness}) end end
function SublimationApparatusMaker.update(dt) if not _G.state then return end; SublimationApparatusMaker.dayTimer=SublimationApparatusMaker.dayTimer+dt; if SublimationApparatusMaker.dayTimer>=30 then SublimationApparatusMaker.dayTimer=0; for i=#SublimationApparatusMaker.activeMaking,1,-1 do local m=SublimationApparatusMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SublimationApparatusMaker.completeMaking(m); table.remove(SublimationApparatusMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SublimationApparatusMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SublimationApparatusMaker.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SublimationApparatusMaker.getStats() return {glassStock=SublimationApparatusMaker.glassStock,clayStock=SublimationApparatusMaker.clayStock,brassStock=SublimationApparatusMaker.brassStock,silverStock=SublimationApparatusMaker.silverStock,goldStock=SublimationApparatusMaker.goldStock,jewelStock=SublimationApparatusMaker.jewelStock,pearlStock=SublimationApparatusMaker.pearlStock,productStock=SublimationApparatusMaker.productStock,numBuildings=#SublimationApparatusMaker.buildings,hasMaker=SublimationApparatusMaker.maker~=nil,makerName=SublimationApparatusMaker.maker and SublimationApparatusMaker.maker.name or "—",makerSkill=SublimationApparatusMaker.maker and SublimationApparatusMaker.maker.skill or 0,activeMaking=#SublimationApparatusMaker.activeMaking,totalProducts=SublimationApparatusMaker.totalProducts} end
return SublimationApparatusMaker
